import re
from datetime import datetime

_DIGITS = frozenset("0123456789")
_GMAIL_DOMAINS = frozenset({"gmail.com", "googlemail.com"})
_OPT_OUT_VALUES = frozenset({"y", "yes", "true", "1"})
_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_EXT_MARKER_RE = re.compile(r"ext|x|#", re.IGNORECASE)
_ZIP_PLUS4_RE = re.compile(r"([0-9]+)-[0-9]{4}")
_TAG_SPLIT_RE = re.compile(r"[;,]")


def _get(row, key):
    return row.get(key) or ""


def _norm_email(raw):
    s = raw.strip()
    lt, gt = s.find("<"), s.rfind(">")
    if lt != -1 and gt > lt:
        s = s[lt + 1:gt]
    s = s.strip().lower()
    if s.count("@") == 1:
        local, domain = s.split("@")
        if domain in _GMAIL_DOMAINS:
            local = local.replace(".", "").split("+", 1)[0]
            s = local + "@gmail.com"
    return s


def _is_valid_email(s):
    if s.count("@") != 1:
        return False
    local, domain = s.split("@")
    return (bool(local) and "." in domain
            and not domain.startswith(".") and not domain.endswith("."))


def _norm_phone(raw):
    m = _EXT_MARKER_RE.search(raw)
    if m:
        raw = raw[:m.start()]
    digits = "".join(c for c in raw if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _norm_zip(raw):
    s = raw.strip()
    m = _ZIP_PLUS4_RE.fullmatch(s)
    if m:
        s = m.group(1)
    if len(s) == 4 and all(c in _DIGITS for c in s):
        s = "0" + s
    if len(s) == 5 and all(c in _DIGITS for c in s):
        return s
    return ""


def _norm_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        s = s.title()
    return s


def _norm_tags(raw):
    return {t.strip().lower() for t in _TAG_SPLIT_RE.split(raw) if t.strip()}


def _parse_updated(raw):
    s = raw.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {raw!r}")


def dedupe_contacts(rows):
    # Normalize each row; drop rows with neither a valid email nor a valid phone.
    kept = []
    for idx, row in enumerate(rows):
        email = _norm_email(_get(row, "email"))
        email = email if _is_valid_email(email) else ""
        phone = _norm_phone(_get(row, "phone"))
        phone = phone if _is_valid_phone(phone) else ""
        if not email and not phone:
            continue
        kept.append({
            "idx": idx,
            "first": _norm_name(_get(row, "first_name")),
            "last": _norm_name(_get(row, "last_name")),
            "zip": _norm_zip(_get(row, "zip")),
            "email": email,
            "phone": phone,
            "source": _get(row, "source").strip().lower(),
            "tags": _norm_tags(_get(row, "tags")),
            "opted_out": _get(row, "opted_out").strip().lower() in _OPT_OUT_VALUES,
            "updated": _parse_updated(_get(row, "updated")),
        })

    # Union-find over rows: same valid email, or same valid phone + same last name.
    n = len(kept)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for j, rec in enumerate(kept):
        if rec["email"]:
            key = rec["email"]
            if key in first_by_email:
                union(j, first_by_email[key])
            else:
                first_by_email[key] = j
        if rec["phone"] and rec["last"]:
            key = (rec["phone"], rec["last"].casefold())
            if key in first_by_phone_last:
                union(j, first_by_phone_last[key])
            else:
                first_by_phone_last[key] = j

    # Groups in order of their earliest row (dict insertion order).
    groups = {}
    for j in range(n):
        groups.setdefault(find(j), []).append(kept[j])

    def pick(members, field):
        cands = [r for r in members if r[field]]
        if not cands:
            return ""
        # Preference: manual source, then most recent updated, then earliest input row.
        ordered = sorted(cands, key=lambda r: r["idx"])
        ordered.sort(key=lambda r: r["updated"], reverse=True)
        ordered.sort(key=lambda r: r["source"] != "manual")
        return ordered[0][field]

    people = []
    for members in groups.values():
        tags = set().union(*(r["tags"] for r in members))
        people.append({
            "first_name": pick(members, "first"),
            "last_name": pick(members, "last"),
            "zip": pick(members, "zip"),
            "email": pick(members, "email"),
            "phone": pick(members, "phone"),
            "source": pick(members, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": "Y" if any(r["opted_out"] for r in members) else "N",
            "updated": max(r["updated"] for r in members).strftime("%Y-%m-%d"),
        })
    return people
